application

;

startFrom       startTime;

startTime       0;

stopAt          endTime;

endTime

;

purgeWrite      3;

writeFormat     ascii;

writePrecision  6;

writeCompression off;

timeFormat      general;

timePrecision   6;

runTimeModifiable true;

