{
    transform1
    {
        type            fieldCoordinateSystemTransform;
        libs            (fieldFunctionObjects);
        writeControl    writeTime;

        fields          (U);
        coordinateSystem
        {
            origin      (0 0 0);
            rotation    none;
        }
    }

    sample1
    {
        type            sets;
        libs            (sampling);
        writeControl    writeTime;
        fields          (U p U:Transformed);
        interpolationScheme cellPoint;
        setFormat       raw;

        sets
        (
            centreLine
            {
                type        uniform;
                axis        x;
                start       (1 0 0);
                end         (2 0 0);
                nPoints     20;
            }
        );
    }
}


